  ["ACTOR_EN_SNOWMAN"] = function(s) return (LOGIC_HELPERS.T(LOGIC_HELPERS.CAN_USE_SWORD(s)) or LOGIC_HELPERS.T(LOGIC_HELPERS.CAN_BE_GORON(s)) or LOGIC_HELPERS.T(LOGIC_HELPERS.CAN_BE_ZORA(s)) or (LOGIC_HELPERS.T(LOGIC_HELPERS.CAN_BE_DEKU(s)) and LOGIC_HELPERS.T(s:has_magic())) or LOGIC_HELPERS.T(s:has_item("ITEM_BOW")) or LOGIC_HELPERS.T(s:has_item("ITEM_DEKU_STICK")) or LOGIC_HELPERS.T(s:has_item("ITEM_HOOKSHOT"))) end,
