-- helper predicates
LOGIC_HELPERS.BREAK_BOULDER_BEFORE_OR_BEAT_ALIENS_DAY = function(s) return ((LOGIC_HELPERS.T(s:time_between(LOGIC_HELPERS.TIME_DAY1_AM_06_00, LOGIC_HELPERS.TIME_NIGHT1_PM_06_00)) and LOGIC_HELPERS.T(LOGIC_HELPERS.CAN_BE_GORON(s)) and LOGIC_HELPERS.T(s:has_item("ITEM_POWDER_KEG"))) or LOGIC_HELPERS.T(s:event("RE_COWS_FROM_ALIENS"))) end
LOGIC_HELPERS.BREAK_BOULDER_BEFORE_OR_BEAT_ALIENS_NIGHT = function(s) return ((LOGIC_HELPERS.T(s:time_between(LOGIC_HELPERS.TIME_NIGHT1_PM_06_00, LOGIC_HELPERS.TIME_NIGHT1_AM_02_30)) and LOGIC_HELPERS.T(LOGIC_HELPERS.CAN_BE_GORON(s)) and LOGIC_HELPERS.T(s:has_item("ITEM_POWDER_KEG"))) or LOGIC_HELPERS.T(s:event("RE_COWS_FROM_ALIENS"))) end
LOGIC_HELPERS.CAN_BE_DEITY = function(s) return (LOGIC_HELPERS.T(s:is_form("DEITY")) or LOGIC_HELPERS.T(s:has_item("ITEM_MASK_FIERCE_DEITY"))) end
LOGIC_HELPERS.CAN_BE_DEKU = function(s) return (LOGIC_HELPERS.T(s:is_form("DEKU")) or LOGIC_HELPERS.T(s:has_item("ITEM_MASK_DEKU"))) end
LOGIC_HELPERS.CAN_BE_GORON = function(s) return (LOGIC_HELPERS.T(s:is_form("GORON")) or LOGIC_HELPERS.T(s:has_item("ITEM_MASK_GORON"))) end
LOGIC_HELPERS.CAN_BE_ZORA = function(s) return (LOGIC_HELPERS.T(s:is_form("ZORA")) or LOGIC_HELPERS.T(s:has_item("ITEM_MASK_ZORA"))) end
LOGIC_HELPERS.CAN_FULLY_CUT_KEATON_GRASS = function(s) return (LOGIC_HELPERS.T(s:has_magic()) and s:equip_value("EQUIP_TYPE_SWORD") >= LOGIC_HELPERS.EQUIP_VALUE_SWORD_RAZOR and LOGIC_HELPERS.T(s:weekeventreg("WEEKEVENTREG_RECEIVED_GREAT_SPIN_ATTACK"))) end
LOGIC_HELPERS.CAN_GROW_BEAN_PLANT = function(s) return (LOGIC_HELPERS.T(s:has_item("ITEM_MAGIC_BEANS")) and (LOGIC_HELPERS.T(s:can_play_song("STORMS")) or (LOGIC_HELPERS.T(s:has_bottle()) and (LOGIC_HELPERS.T(s:can_access("SPRING_WATER")) or LOGIC_HELPERS.T(s:can_access("HOT_SPRING_WATER")))))) end
LOGIC_HELPERS.CAN_HOOK_SCARECROW = function(s) return (LOGIC_HELPERS.T(s:has_item("ITEM_OCARINA_OF_TIME")) and LOGIC_HELPERS.T(s:has_item("ITEM_HOOKSHOT")) and LOGIC_HELPERS.T(s:can_play_notes("OCARINA_SONG_SCARECROW_SPAWN"))) end
LOGIC_HELPERS.CAN_LIGHT_TORCH_NEAR_ANOTHER = function(s) return (LOGIC_HELPERS.T(s:has_item("ITEM_DEKU_STICK")) or LOGIC_HELPERS.T(s:can_use_magic_arrow("FIRE"))) end
LOGIC_HELPERS.CAN_RIDE_EPONA = function(s) return LOGIC_HELPERS.T(s:can_play_song("EPONA")) end
LOGIC_HELPERS.CAN_TRAVERSE_WAIST_DEEP_WATER = function(s) return (LOGIC_HELPERS.T(s:ability("SWIM")) or LOGIC_HELPERS.T(LOGIC_HELPERS.CAN_BE_DEKU(s)) or LOGIC_HELPERS.T(LOGIC_HELPERS.CAN_BE_ZORA(s)) or LOGIC_HELPERS.T(LOGIC_HELPERS.CAN_BE_GORON(s))) end
LOGIC_HELPERS.CAN_USE_DAY2_RAIN_BEAN = function(s) return (LOGIC_HELPERS.T(LOGIC_HELPERS.CAN_GROW_BEAN_PLANT(s)) or (LOGIC_HELPERS.T(s:has_item("ITEM_MAGIC_BEANS")) and LOGIC_HELPERS.T(LOGIC_HELPERS.CLOCK_DAY2(s)))) end
LOGIC_HELPERS.CAN_USE_EXPLOSIVE = function(s) return (LOGIC_HELPERS.T(s:has_item("ITEM_BOMB")) or LOGIC_HELPERS.T(s:has_item("ITEM_BOMBCHU")) or (LOGIC_HELPERS.T(s:has_item("ITEM_MASK_BLAST")) and s:equip_value("EQUIP_TYPE_SHIELD") > LOGIC_HELPERS.EQUIP_VALUE_SHIELD_NONE)) end
LOGIC_HELPERS.CAN_USE_HUMAN_SWORD = function(s) return s:equip_value("EQUIP_TYPE_SWORD") >= LOGIC_HELPERS.EQUIP_VALUE_SWORD_KOKIRI end
LOGIC_HELPERS.CAN_USE_PROJECTILE = function(s) return (LOGIC_HELPERS.T(s:has_item("ITEM_BOW")) or LOGIC_HELPERS.T(s:has_item("ITEM_HOOKSHOT")) or (LOGIC_HELPERS.T(LOGIC_HELPERS.CAN_BE_DEKU(s)) and LOGIC_HELPERS.T(s:has_magic())) or LOGIC_HELPERS.T(LOGIC_HELPERS.CAN_BE_ZORA(s))) end
LOGIC_HELPERS.CAN_USE_SWORD = function(s) return (LOGIC_HELPERS.T(LOGIC_HELPERS.CAN_USE_HUMAN_SWORD(s)) or LOGIC_HELPERS.T(s:has_item("ITEM_SWORD_GREAT_FAIRY")) or LOGIC_HELPERS.T(LOGIC_HELPERS.CAN_BE_DEITY(s))) end
LOGIC_HELPERS.CLOCK_DAY1 = function(s) return LOGIC_HELPERS.T(s:owns_half_day(0)) end
LOGIC_HELPERS.CLOCK_DAY2 = function(s) return LOGIC_HELPERS.T(s:owns_half_day(2)) end
LOGIC_HELPERS.CLOCK_DAY3 = function(s) return LOGIC_HELPERS.T(s:owns_half_day(4)) end
LOGIC_HELPERS.CLOCK_NIGHT1 = function(s) return LOGIC_HELPERS.T(s:owns_half_day(1)) end
LOGIC_HELPERS.CLOCK_NIGHT2 = function(s) return LOGIC_HELPERS.T(s:owns_half_day(3)) end
LOGIC_HELPERS.CLOCK_NIGHT3 = function(s) return LOGIC_HELPERS.T(s:owns_half_day(5)) end
LOGIC_HELPERS.CanGetPastBigOcto = function(s) return (LOGIC_HELPERS.T(s:event("RE_SOUTHERN_SWAMP_RIDE_BOAT")) or LOGIC_HELPERS.T(LOGIC_HELPERS.CanGetPastBigOctoWithoutBoat(s))) end
LOGIC_HELPERS.CanGetPastBigOctoWithoutBoat = function(s) return ((LOGIC_HELPERS.T(s:event("RE_SOUTHERN_SWAMP_KILL_OCTOROK")) and LOGIC_HELPERS.T(LOGIC_HELPERS.CAN_BE_DEKU(s))) or (LOGIC_HELPERS.T(s:event("RE_CLEARED_WOODFALL_TEMPLE")) and LOGIC_HELPERS.T(LOGIC_HELPERS.CAN_TRAVERSE_WAIST_DEEP_WATER(s)))) end
LOGIC_HELPERS.ClockFilter = function(s) return (not LOGIC_HELPERS.T(LOGIC_HELPERS.SettingClocks(s)) or (LOGIC_HELPERS.T(LOGIC_HELPERS.IS_DAY1(s)) or LOGIC_HELPERS.T(LOGIC_HELPERS.IS_NIGHT1(s)) or LOGIC_HELPERS.T(LOGIC_HELPERS.IS_DAY2(s)) or LOGIC_HELPERS.T(LOGIC_HELPERS.IS_NIGHT2(s)) or LOGIC_HELPERS.T(LOGIC_HELPERS.IS_DAY3(s)) or LOGIC_HELPERS.T(LOGIC_HELPERS.IS_NIGHT3(s)))) end
LOGIC_HELPERS.FINAL_DAY = function(s) return (LOGIC_HELPERS.T(LOGIC_HELPERS.IS_DAY3(s)) or LOGIC_HELPERS.T(LOGIC_HELPERS.IS_NIGHT3(s))) end
LOGIC_HELPERS.FIRST_DAY = function(s) return (LOGIC_HELPERS.T(LOGIC_HELPERS.IS_DAY1(s)) or LOGIC_HELPERS.T(LOGIC_HELPERS.IS_NIGHT1(s))) end
LOGIC_HELPERS.FOUND_ALL_FROGS = function(s) return (LOGIC_HELPERS.T(s:weekeventreg("WEEKEVENTREG_33_01")) and LOGIC_HELPERS.T(s:weekeventreg("WEEKEVENTREG_32_40")) and LOGIC_HELPERS.T(s:weekeventreg("WEEKEVENTREG_32_80")) and LOGIC_HELPERS.T(s:weekeventreg("WEEKEVENTREG_33_02"))) end
LOGIC_HELPERS.GBT_CAN_REVERSE_WATER_FLOW = function(s) return (LOGIC_HELPERS.T(s:event("RE_GREAT_BAY_RED_SWITCH_1")) and LOGIC_HELPERS.T(s:event("RE_GREAT_BAY_RED_SWITCH_2")) and LOGIC_HELPERS.T(s:has_item("ITEM_HOOKSHOT"))) end
LOGIC_HELPERS.GBT_GREEN_SWITCH_FLOW = function(s) return (LOGIC_HELPERS.T(s:event("RE_GREAT_BAY_GREEN_SWITCH_1")) and LOGIC_HELPERS.T(s:event("RE_GREAT_BAY_GREEN_SWITCH_2")) and LOGIC_HELPERS.T(s:event("RE_GREAT_BAY_GREEN_SWITCH_3"))) end
LOGIC_HELPERS.IS_DAY = function(s) return (LOGIC_HELPERS.T(LOGIC_HELPERS.IS_DAY1(s)) or LOGIC_HELPERS.T(LOGIC_HELPERS.IS_DAY2(s)) or LOGIC_HELPERS.T(LOGIC_HELPERS.IS_DAY3(s))) end
LOGIC_HELPERS.IS_DAY1 = function(s) return (LOGIC_HELPERS.T(s:raw_before(LOGIC_HELPERS.TIME_NIGHT1_PM_06_00)) and LOGIC_HELPERS.T(LOGIC_HELPERS.CLOCK_DAY1(s))) end
LOGIC_HELPERS.IS_DAY2 = function(s) return (LOGIC_HELPERS.T(s:raw_between(LOGIC_HELPERS.TIME_DAY2_AM_06_00, LOGIC_HELPERS.TIME_NIGHT2_PM_06_00)) and LOGIC_HELPERS.T(LOGIC_HELPERS.CLOCK_DAY2(s))) end
LOGIC_HELPERS.IS_DAY3 = function(s) return (LOGIC_HELPERS.T(s:raw_between(LOGIC_HELPERS.TIME_DAY3_AM_06_00, LOGIC_HELPERS.TIME_NIGHT3_PM_06_00)) and LOGIC_HELPERS.T(LOGIC_HELPERS.CLOCK_DAY3(s))) end
LOGIC_HELPERS.IS_NIGHT = function(s) return (LOGIC_HELPERS.T(LOGIC_HELPERS.IS_NIGHT1(s)) or LOGIC_HELPERS.T(LOGIC_HELPERS.IS_NIGHT2(s)) or LOGIC_HELPERS.T(LOGIC_HELPERS.IS_NIGHT3(s))) end
LOGIC_HELPERS.IS_NIGHT1 = function(s) return (LOGIC_HELPERS.T(s:raw_between(LOGIC_HELPERS.TIME_NIGHT1_PM_06_00, LOGIC_HELPERS.TIME_DAY2_AM_06_00)) and LOGIC_HELPERS.T(LOGIC_HELPERS.CLOCK_NIGHT1(s))) end
LOGIC_HELPERS.IS_NIGHT2 = function(s) return (LOGIC_HELPERS.T(s:raw_between(LOGIC_HELPERS.TIME_NIGHT2_PM_06_00, LOGIC_HELPERS.TIME_DAY3_AM_06_00)) and LOGIC_HELPERS.T(LOGIC_HELPERS.CLOCK_NIGHT2(s))) end
LOGIC_HELPERS.IS_NIGHT3 = function(s) return (LOGIC_HELPERS.T(s:raw_after(LOGIC_HELPERS.TIME_NIGHT3_PM_06_00)) and LOGIC_HELPERS.T(LOGIC_HELPERS.CLOCK_NIGHT3(s))) end
LOGIC_HELPERS.MIDNIGHT = function(s) return (LOGIC_HELPERS.T(s:time_between(LOGIC_HELPERS.TIME_NIGHT1_AM_12_00, LOGIC_HELPERS.TIME_DAY2_AM_06_00)) or LOGIC_HELPERS.T(s:time_between(LOGIC_HELPERS.TIME_NIGHT2_AM_12_00, LOGIC_HELPERS.TIME_DAY3_AM_06_00)) or LOGIC_HELPERS.T(s:time_after(LOGIC_HELPERS.TIME_NIGHT3_AM_12_00))) end
LOGIC_HELPERS.MeetsMoonRequirements = function(s) return (s:remains_count() >= s:opt("RO_ACCESS_MOON_REMAINS_COUNT") and s:moon_mask_count() >= s:opt("RO_ACCESS_MOON_MASKS_COUNT")) end
LOGIC_HELPERS.SECOND_DAY = function(s) return (LOGIC_HELPERS.T(LOGIC_HELPERS.IS_DAY2(s)) or LOGIC_HELPERS.T(LOGIC_HELPERS.IS_NIGHT2(s))) end
LOGIC_HELPERS.SettingClocks = function(s) return s:opt("RO_CLOCK_SHUFFLE") ~= 0 end
LOGIC_HELPERS.CanKillEnemy = function(s, actor)
  if LOGIC_HELPERS.T(s:opt('RO_SHUFFLE_ENEMY_SOULS')) and not s:have_enemy_soul(actor) then
    return false
  end
  local fn = LOGIC_HELPERS.CAN_KILL_ENEMY[actor]
  if fn == nil then
    error('CanKillEnemy: no logic for ' .. tostring(actor))
  end
  return fn(s)
end